// Reliable live fetch — uses Supabase proxy for POST + falls back through CORS proxies for GET.
async function fetchWithProxy(url: string, opts: RequestInit = {}, _timeoutMs = 12000): Promise<any> {
  const isPost = (opts.method ?? "GET").toUpperCase() === "POST";
  if (isPost) {
    const body = typeof opts.body === "string" ? JSON.parse(opts.body) : opts.body;
    return liveFetchPOST(url, body);
  }
  return liveFetch(url, opts as any);
}

